<template>
 <main class="task-center">
  <header class="task-center-head"><div><h1>待办中心</h1><p>{{captain?'处理当前决策，跟进已派发的执行任务。':'按本次任务要求执行，完成后提交结果。'}}</p></div><label class="task-search"><span class="sr-only">搜索任务、事件或设备</span><input v-model="query" type="search" placeholder="搜索任务、事件或设备"/></label></header>
  <nav class="task-center-tabs" aria-label="待办分类"><button v-for="item in tabs" :key="item.key" :class="{active:tab===item.key}" :aria-current="tab===item.key?'page':undefined" @click="selectTab(item.key)">{{item.label}}<span>{{work[item.key].length}}</span></button></nav>
  <section class="task-center-body">
   <div class="task-center-intro"><div><h2>{{activeLabel}}</h2><p>{{tabDescription}}</p></div><label>类型<select v-model="filter" aria-label="记录类型"><option value="">全部类型</option><option v-if="captain&&tab!=='assigned'" value="decision">决策与确认</option><option value="task">执行任务</option></select></label></div>
   <label v-if="tab==='assigned'" class="task-history-filter">派发记录 <select v-model="assignedFilter"><option value="active">未完成</option><option value="all">全部历史</option></select></label>
   <div v-if="items.length" class="work-card-grid">
    <article v-for="item in items" :key="item.id" class="work-card" :class="{'is-decision':item.kind==='decision','is-done':item.done}" :data-work-id="item.id">
     <header><span class="work-kind">{{item.type}}</span><small>{{item.number||item.eventNumber}}</small><span class="work-state">{{item.status}}</span></header>
     <h3><button @click="open(item)">{{item.title}}</button></h3>
     <p class="work-summary">{{item.summary}}</p>
     <div class="work-event"><span>关联事件</span><span>{{item.eventTitle}} · {{store.state.events[item.eventId]?.status}}</span></div>
     <dl><div><dt>{{item.kind==='task'?'执行人':'处理人'}}</dt><dd>{{item.owner}}</dd></div><div><dt>{{item.kind==='task'?'要求完成':'记录时间'}}</dt><dd>{{timeText(item.deadline||item.at)}}</dd></div></dl>
     <footer><span v-if="item.kind==='task'">{{item.progress}} / {{item.total}} 项{{item.done?'已提交':'已填写'}}</span><span v-else>{{item.device}} · {{item.eventType}}</span><button @click="open(item)">{{item.actionLabel}} <span aria-hidden="true">→</span></button></footer>
    </article>
   </div>
   <section v-else class="task-center-empty"><strong>{{query||filter?'没有匹配的记录':tab==='pending'?'当前没有需要您处理的待办':'暂无'+activeLabel+'记录'}}</strong><p>{{tab==='pending'?(captain?'已派发的任务在“我派发的”中跟进；结果回交后会产生新的决策待办。':'任务提交后进入“已完成”；新的派发任务会在这里显示。'):'可切换分类或调整搜索条件查看其他记录。'}}</p></section>
  </section>
 </main>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useEventLifecycleStore} from '../stores/eventLifecycleStore'
import {timeText} from '../workflow/eventLifecycle'
const store=useEventLifecycleStore(),route=useRoute(),router=useRouter(),query=ref(''),filter=ref(''),tab=ref('pending'),assignedFilter=ref('active')
const captain=computed(()=>store.state.role==='captain'),work=computed(()=>store.workItems)
const tabs=computed(()=>[{key:'pending',label:'待我处理'},...(captain.value?[{key:'assigned',label:'我派发的'}]:[]),{key:'completed',label:'已完成'},{key:'all',label:'全部记录'}])
const activeLabel=computed(()=>tabs.value.find(t=>t.key===tab.value)?.label)
const tabDescription=computed(()=>({pending:'只显示当前需要本人执行、决策或确认的工作。',assigned:'查看本人派发的任务及执行进度；派发记录与执行人看到的是同一项任务。',completed:captain.value?'已完成的决策与确认记录，保留当时的处理依据。':'已提交的任务和报告，可回看本轮步骤及实际结果。',all:captain.value?'汇总本人可见的执行任务与决策记录。':'仅显示本人负责的任务及完成记录。'}[tab.value]))
const items=computed(()=>work.value[tab.value].filter(item=>(tab.value!=='assigned'||assignedFilter.value==='all'||!item.done)&&(!filter.value||item.kind===filter.value)&&[item.title,item.eventTitle,item.eventNumber,item.number,item.device,item.owner].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
function selectTab(value){tab.value=value;filter.value='';router.replace({path:'/event',query:value==='pending'?{}:{view:value}})}
function open(item){router.push({...item.location,query:{...item.location.query,returnView:tab.value}})}
watch(()=>[route.name,route.query.view,store.state.role],()=>{if(route.name==='EventCenter')tab.value=tabs.value.some(t=>t.key===route.query.view)?route.query.view:'pending';else if(!tabs.value.some(t=>t.key===tab.value))tab.value='pending';filter.value=''},{immediate:true})
</script>
<style scoped>
.task-center{width:100%;min-width:0;height:100%;padding:24px;display:flex;flex-direction:column;box-sizing:border-box;color:#34465b;background:#f3f5f8}.task-center-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:22px}.task-center h1{font-size:24px;font-weight:600;margin:0 0 6px;color:#28394c}.task-center-head p,.task-center-intro p{margin:0;color:#7a8797;font-size:13px;line-height:1.6}.task-search input{width:260px;max-width:100%;padding:10px 13px;border:1px solid #dce1e6;border-radius:8px;background:#fff;font:inherit;font-size:13px;color:#42556c}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.task-center-tabs{display:flex;gap:26px;border-bottom:1px solid #dce1e6;flex:none;padding:0 2px}.task-center-tabs button{display:flex;align-items:center;gap:8px;padding:0 0 14px;background:none;border:0;border-bottom:2px solid transparent;font:inherit;font-size:14px;color:#7a8797;cursor:pointer}.task-center-tabs button.active{border-bottom-color:#ae8b4f;color:#886a38}.task-center-tabs span{font-size:11px;background:#e8ecf0;padding:2px 6px;border-radius:5px;min-width:16px;text-align:center}.task-center-tabs button.active span{background:#ebe4d7;color:#886a38}.task-center-body{overflow:auto;flex:1;min-height:0;padding:20px 2px;scrollbar-gutter:stable}.task-center-intro{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:18px}.task-center h2{font-size:16px;margin:0 0 6px;font-weight:600}.task-center-intro label{display:flex;gap:10px;align-items:center;white-space:nowrap;color:#7a8797;font-size:12px}.task-center-intro select{padding:8px 10px;border:1px solid #dce1e6;border-radius:7px;background:#fff;color:#52667e;font:inherit}
.work-card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:16px}.work-card{display:flex;flex-direction:column;min-width:0;border:1px solid #e0e4e9;border-radius:10px;background:#fff;padding:18px 20px 0;transition:box-shadow .15s,border-color .15s}.work-card:hover{border-color:#cab894;box-shadow:0 4px 16px #253b4d08}.work-card>header{display:flex;align-items:center;flex-wrap:wrap;gap:7px;font-size:11px}.work-kind{color:#477d9a;background:#edf4f8;border-radius:4px;padding:3px 6px;font-weight:500}.is-decision .work-kind{background:#f5efdf;color:#997438}.is-done .work-kind{background:#edf3f0;color:#5a7d6d}.work-card small{font-size:10px;color:#8c99a9;overflow-wrap:anywhere}.work-state{margin-left:auto;color:#8a785a;white-space:nowrap}.work-card h3{margin:16px 0 10px;font-size:17px;line-height:1.6}.work-card h3 button{padding:0;border:0;background:none;font:inherit;color:#304258;text-align:left;cursor:pointer}.work-summary{font-size:13px;line-height:1.8;color:#718298;margin:0 0 18px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}.work-event{margin-top:auto;display:flex;gap:10px;font-size:12px;line-height:1.7;color:#5f7288;padding-bottom:13px;border-bottom:1px solid #edf0f3}.work-event>span:first-child{white-space:nowrap;color:#96a0ad}.work-card dl{margin:12px 0 16px;font-size:12px;line-height:1.8;display:grid;gap:6px}.work-card dl>div{display:flex;gap:14px}.work-card dt{color:#96a0ad;min-width:48px}.work-card dd{margin:0;color:#65788e}.work-card footer{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid #edf0f3;min-height:49px;font-size:12px;color:#8b98a7}.work-card footer button{border:0;background:none;padding:8px 0;font:inherit;color:#94733e;cursor:pointer}.work-card footer button span{padding-left:6px}.task-center-empty{padding:70px 20px;text-align:center;border:1px dashed #dce1e7;border-radius:10px;background:#ffffff80}.task-center-empty strong{font-size:17px;font-weight:500}.task-center-empty p{font-size:13px;color:#8794a4;line-height:1.8}.task-center button:focus-visible{outline:2px solid #b99554;outline-offset:4px}
@media(min-width:1900px){.work-card-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:760px){.task-center{padding:16px}.task-center-head{flex-direction:column;align-items:stretch;gap:12px}.task-search input{width:100%;box-sizing:border-box}.task-center-tabs{gap:18px;overflow:auto}.task-center-tabs button{white-space:nowrap;font-size:13px}.task-center-intro{align-items:flex-start}.task-center-intro p{font-size:12px}.work-card-grid{grid-template-columns:1fr}.work-card{padding:16px 16px 0}.task-center-tabs span{min-width:12px}}
</style>
